import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Whole archive/field audit; the character marker never links to an earlier action generation. */
public final class CompanionRoleIdentityDelta {
 static final String P="local/lito381/server/";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n))).accept(c,0);return c;}
 public static void main(String[] a)throws Exception{try(var before=new JarFile(a[0]);var after=new JarFile(a[1])){
  var expected=new TreeSet<String>();for(var n:List.of("BattleTimedStatus","NativeCompanionTargets$Scope","NativeCompanionTargets","NativeCompanionPlacement$State","NativeCompanionPlacement$Transition","NativePlayerCommit","NativeStaticNpcMotion"))expected.add(P+n+".class");var additions=new TreeSet<String>();for(var n:List.of("NativeCompanionRoleIdentity","NativeCompanionRoleIdentity$Epoch","NativeCompanionRoleIdentity$Role"))additions.add(P+n+".class");var changed=new TreeSet<String>();var names=new HashSet<String>();
  for(var e:Collections.list(before.entries())){names.add(e.getName());var n=after.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed "+e.getName());if(!Arrays.equals(before.getInputStream(e).readAllBytes(),after.getInputStream(n).readAllBytes()))changed.add(e.getName());}
  var fresh=new TreeSet<String>();for(var e:Collections.list(after.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(expected)||!fresh.equals(additions))throw new AssertionError("archive delta "+changed+" "+fresh);
  int visibility=0;for(var name:changed){var b=read(before,name);var c=read(after,name);if(b.fields.size()!=c.fields.size())throw new AssertionError("new field "+name);for(int i=0;i<b.fields.size();i++){var x=b.fields.get(i);var y=c.fields.get(i);if(!x.name.equals(y.name)||!x.desc.equals(y.desc)||!Objects.equals(x.value,y.value))throw new AssertionError("field schema "+name);int flags=x.access;if(name.equals(P+"BattleTimedStatus.class")&&x.name.equals("sourcePoisonLifecycle")){flags|=Opcodes.ACC_VOLATILE;visibility++;}if(y.access!=flags)throw new AssertionError("field visibility "+name+" "+x.name);}}
  if(visibility!=1)throw new AssertionError("one existing role-slot visibility change");
  for(var name:fresh){var c=read(after,name);if(c.fields.stream().anyMatch(f->(f.access&Opcodes.ACC_STATIC)!=0))throw new AssertionError("new static state "+name);if(name.endsWith("$Epoch.class")){if(c.fields.size()!=1||!c.fields.get(0).desc.equals("L"+P+"NativeCompanionRoleIdentity$Role;")||(c.fields.get(0).access&Opcodes.ACC_FINAL)==0)throw new AssertionError("bounded action token");}else if(name.endsWith("$Role.class")){if(c.fields.size()!=1||!c.fields.get(0).desc.equals("Z")||(c.fields.get(0).access&Opcodes.ACC_VOLATILE)==0)throw new AssertionError("bounded role marker");}else if(!c.fields.isEmpty())throw new AssertionError("stateless helper");
   for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==Opcodes.NEW&&(t.desc.equals("java/lang/Thread")||t.desc.contains("ThreadLocal")||t.desc.contains("ThreadPool")||t.desc.equals("java/util/Timer")))throw new AssertionError("new execution owner "+t.desc);if(n instanceof MethodInsnNode call&&(call.owner.startsWith("java/sql/")||call.owner.startsWith("javax/sql/")||call.owner.startsWith("java/nio/file/")||call.owner.contains("AccountRepository")||call.owner.endsWith("GameStateStore")||call.name.equals("nativeDeInventory")))throw new AssertionError("new SQL/file/player-inventory dependency "+call.owner+"."+call.name);}
  }
  for(var n:List.of("ClientSession","NativePlayerCommit$Binding","NativePairedCastSafety","NativePlayerLifetime")){var path=P+n+".class";if(!Arrays.equals(before.getInputStream(before.getJarEntry(path)).readAllBytes(),after.getInputStream(after.getJarEntry(path)).readAllBytes()))throw new AssertionError("strict player/pair/lifetime contract changed "+n);}
 }System.out.println("PASS exact seven changed/three fresh classes; no added fields; one existing slot made volatile; strict player bindings/pair/lifetime classes unchanged; bounded Role/Epoch without predecessor/player/Hub/global references; no new workers, clocks, SQL/file or inventory dependency");}
}
